  // ---- setup guides (developer-facing: Korean and English)
  setupTitle: ['연결 설정', 'Connection setup', '接続の設定', '连接设置', 'Configurar conexión'],
  guideLead: ['처음 한 번만 설정하면, 이후에는 태블릿에서 필기한 내용이 자동으로 이 휴대폰에 나타납니다.', 'Set this up once; after that, what you write on your tablet shows up on this phone automatically.', '一度設定すれば、その後はタブレットで書いた内容が自動でこのスマホに表示されます。', '只需设置一次，之后在平板上写的内容会自动出现在这部手机上。', 'Configúralo una vez; después, lo que escribas en la tableta aparecerá automáticamente en este teléfono.'],
  guideBackupTitle: ['노트 앱에서 PDF 자동 백업 켜기', 'Turn on PDF auto-backup in your note app', 'ノートアプリで PDF 自動バックアップをオンにする', '在笔记应用中开启 PDF 自动备份', 'Activa la copia automática en PDF en tu app de notas'],
  guideBackupSteps: ['<li>태블릿의 노트 앱 설정에서 <b>자동 백업</b>을 켭니다</li><li>백업 위치는 <b>Google 드라이브</b>, 파일 형식은 <b>PDF</b>로 선택합니다</li>', "<li>In your tablet note app's settings, turn on <b>auto-backup</b></li><li>Choose <b>Google Drive</b> as the location and <b>PDF</b> as the format</li>", '<li>タブレットのノートアプリの設定で<b>自動バックアップ</b>をオンにします</li><li>保存先は<b>Google ドライブ</b>、形式は<b>PDF</b>を選びます</li>', '<li>在平板笔记应用的设置中开启<b>自动备份</b></li><li>备份位置选择<b>Google 云端硬盘</b>，格式选择<b>PDF</b></li>', '<li>En los ajustes de la app de notas de tu tableta, activa la <b>copia de seguridad automática</b></li><li>Elige <b>Google Drive</b> como ubicación y <b>PDF</b> como formato</li>'],
  guideBackupNote: ['예: GoodNotes는 <b>설정 → 클라우드 및 백업 → 자동 백업</b>에 있습니다. 노트를 수정하면 앱이 드라이브에 PDF를 다시 올리고, 이 뷰어가 그 PDF를 읽어 옵니다.', 'Example: in GoodNotes it is under <b>Settings → Cloud & Backup → Auto-Backup</b>. When you edit a note, the app re-uploads the PDF to Drive and this viewer picks it up.', '例: GoodNotes では<b>設定 → クラウドとバックアップ → 自動バックアップ</b>にあります。ノートを編集するとアプリがドライブに PDF を再アップロードし、このビューアがそれを読み込みます。', '例如：GoodNotes 位于<b>设置 → 云和备份 → 自动备份</b>。修改笔记后，应用会将 PDF 重新上传到云端硬盘，本查看器会读取它。', 'Ejemplo: en GoodNotes está en <b>Ajustes → Nube y copia de seguridad → Copia automática</b>. Al editar una nota, la app vuelve a subir el PDF a Drive y este visor lo recoge.'],
  guideCloudTitle: ['Google Cloud에 이 앱 등록하기 (무료)', 'Register this app in Google Cloud (free)'],
  guideCloudTitleWeb: ['Google OAuth 클라이언트 ID 만들기 (무료)', 'Create a Google OAuth client ID (free)'],
  guideStepProject: ['<a href="https://console.cloud.google.com/projectcreate" target="_blank" rel="noopener">Google Cloud 콘솔</a>에서 새 프로젝트 만들기', 'Create a new project in the <a href="https://console.cloud.google.com/projectcreate" target="_blank" rel="noopener">Google Cloud console</a>'],
  guideStepApi: ['<a href="https://console.cloud.google.com/apis/library/drive.googleapis.com" target="_blank" rel="noopener">Google Drive API</a> → <b>사용</b>', '<a href="https://console.cloud.google.com/apis/library/drive.googleapis.com" target="_blank" rel="noopener">Google Drive API</a> → <b>Enable</b>'],
  guideStepConsent: ['<a href="https://console.cloud.google.com/auth/branding" target="_blank" rel="noopener">OAuth 동의 화면</a> 구성 → 대상 <b>외부</b>', 'Configure the <a href="https://console.cloud.google.com/auth/branding" target="_blank" rel="noopener">OAuth consent screen</a> → audience <b>External</b>'],
  guideStepTesters: ['<a href="https://console.cloud.google.com/auth/audience" target="_blank" rel="noopener">대상(Audience)</a> → <b>테스트 사용자 → + Add users</b> → 휴대폰에서 쓰는 Gmail 주소 추가 → 저장 <b>(빠뜨리면 “Access blocked” 오류)</b>', '<a href="https://console.cloud.google.com/auth/audience" target="_blank" rel="noopener">Audience</a> → <b>Test users → + Add users</b> → add the Gmail address you use on your phone → Save <b>(otherwise you get “Access blocked”)</b>'],
  guideStepClientAndroid: ['<a href="https://console.cloud.google.com/auth/clients" target="_blank" rel="noopener">클라이언트</a> → <b>클라이언트 만들기</b> → 유형 <b>Android</b>', '<a href="https://console.cloud.google.com/auth/clients" target="_blank" rel="noopener">Clients</a> → <b>Create client</b> → type <b>Android</b>'],
  guideStepClientWeb: ['<a href="https://console.cloud.google.com/auth/clients" target="_blank" rel="noopener">클라이언트</a> → <b>클라이언트 만들기</b> → 유형 <b>웹 애플리케이션</b>', '<a href="https://console.cloud.google.com/auth/clients" target="_blank" rel="noopener">Clients</a> → <b>Create client</b> → type <b>Web application</b>'],
  guideStepCreateDone: ['<b>만들기</b>를 누르면 끝 (클라이언트 ID를 복사할 필요 없음)', "Tap <b>Create</b> and you're done (no need to copy the client ID)"],
