  cloudInstead: ['또는 다른 클라우드에서 가져오기', 'Or bring notes from another cloud', 'またはその他のクラウドから読み込む', '或从其他云盘导入', 'O traer notas de otra nube'],
  cloudAddFolderSub: ['{name}에서 GoodNotes 백업 폴더 고르기', 'Choose your GoodNotes backup folder on {name}', '{name} の GoodNotes バックアップフォルダを選ぶ', '选择 {name} 上的 GoodNotes 备份文件夹', 'Elige tu carpeta de copias de GoodNotes en {name}'],
