let lang = 'en';

/** The language in effect: the user's choice, else the first supported device language, else English. */
export function resolveLang() {
  const chosen = settings.lang;
  if (chosen && chosen !== 'auto' && ORDER.includes(chosen)) return chosen;
  for (const l of navigator.languages || [navigator.language]) {
    const base = String(l || '').toLowerCase().split('-')[0];
    if (ORDER.includes(base)) return base;
  }
  return 'en';
}

export function applyLang() {
  lang = resolveLang();
  document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
  return lang;
}

export function currentLang() { return lang; }
/** Pieces of information on one line, joined the way each language lists things (not with a dot). */
const LIST_SEP = { ko: ', ', en: ', ', ja: '、', zh: '，', es: ', ' };
export const listSep = () => LIST_SEP[lang] || ', ';
export function joinList(parts) { return parts.filter(Boolean).join(listSep()); }
export function locale() { return LOCALES[lang]; }

export function t(key, vars) {
  let row = M[key];
  const idx = ORDER.indexOf(lang);
  if (vars && Number(vars.n) === 1) {
    const one = M[key + '_one'];
    if (one && one[idx] != null) row = one;
  }
  let s = row ? (row[idx] ?? row[1] ?? row[0]) : key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? ''));
  return s;
}

applyLang();
